PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?p ?o WHERE {
  ?s brick:isFedBy ?o .
} LIMIT 50

SELECT ?zone ?label WHERE {
  ?ahu a brick:Air_Handling_Unit .
  FILTER (CONTAINS(STR(?ahu), "AHU03"))
  ?ahu brick:feeds ?zone .
  ?zone rdfs:label ?label .
}

SELECT ?zone ?pt WHERE {
  ?zone a brick:Zone .
  ?pt brick:isPointOf ?zone .
  ?pt rdf:type brick:Air_Temperature .
} LIMIT 50

